'use client'

import React, { useState } from 'react';
import { SearchIcon, ChevronDownIcon } from 'lucide-react';

type FaqCategory = 'Getting Started' | 'Account Management' | 'Posting Jobs' | 'Finding Work' | 'Payments' | 'Safety & Security';

export default function Help() {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState<FaqCategory>('Getting Started');
  const categories: FaqCategory[] = ['Getting Started', 'Account Management', 'Posting Jobs', 'Finding Work', 'Payments', 'Safety & Security'];
  const faqs: Record<FaqCategory, { question: string; answer: string; }[]> = {
    'Getting Started': [{
      question: 'How do I create an account?',
      answer: "To create an account, click on the 'Sign In' button in the top right corner of the homepage, then select 'Register'. Follow the prompts to complete your registration as either an employer or a job seeker."
    }, {
      question: "What's the difference between employer and job seeker accounts?",
      answer: 'Employer accounts allow you to post jobs and hire workers, while job seeker accounts allow you to apply for jobs and showcase your skills to potential employers. Each account type has different features tailored to their specific needs.'
    }, {
      question: 'Is it free to sign up?',
      answer: 'Yes, creating a basic account is completely free. We offer a Free Tier that allows you to access core features. For additional functionality, you can upgrade to our Paid or Enterprise plans.'
    }, {
      question: 'How do I get verified?',
      answer: "Verification is available on our Paid and Enterprise plans. Once subscribed, you'll need to submit identification documents and complete a background check process. Verified accounts receive a badge that increases trust with other users."
    }],
    'Account Management': [{
      question: 'How do I edit my profile?',
      answer: 'To edit your profile, sign in to your account and navigate to the Account tab. From there, you can update your personal information, contact details, profile picture, and other settings.'
    }, {
      question: 'Can I change my account type?',
      answer: "Yes, you can switch between employer and job seeker accounts. Go to Account Settings and select 'Change Account Type'. Note that this will require you to complete additional profile information specific to the new account type."
    }, {
      question: 'How do I reset my password?',
      answer: "Click on 'Sign In', then select 'Forgot password?' Enter the email address associated with your account, and we'll send you instructions to reset your password."
    }, {
      question: 'How do I delete my account?',
      answer: "To delete your account, go to Account Settings and select 'Delete Account'. Please note that this action is permanent and will remove all your data from our platform."
    }],
    'Posting Jobs': [{
      question: 'How do I post a job?',
      answer: "Sign in to your employer account, navigate to your dashboard, and click on 'Post a Job'. Fill out the job details form, including title, description, requirements, and compensation, then submit it for review."
    }, {
      question: 'How long does it take for my job posting to go live?',
      answer: 'Most job postings go live immediately after submission. However, some may require manual review, which can take up to 24 hours.'
    }, {
      question: "Can I edit a job posting after it's published?",
      answer: "Yes, you can edit your job posting at any time. Go to your dashboard, find the job in your listings, and click 'Edit'. Keep in mind that significant changes may require re-approval."
    }, {
      question: 'How many jobs can I post?',
      answer: 'Free Tier accounts can post up to 3 jobs per month. Paid Plan subscribers can post unlimited jobs. Enterprise accounts also have unlimited postings plus additional bulk posting tools.'
    }],
    'Finding Work': [{
      question: 'How do I search for jobs?',
      answer: "Use the 'Find Jobs' section to browse available opportunities. You can filter by category, location, job type, and other criteria to narrow down your search."
    }, {
      question: 'How do I apply for a job?',
      answer: "When you find a job you're interested in, click on 'Apply Now'. You'll be prompted to submit your application, which may include a cover message and any requested documents or portfolio items."
    }, {
      question: 'How can I make my profile stand out to employers?',
      answer: 'Complete your profile with detailed information about your skills, experience, and qualifications. Add a professional photo, request reviews from previous clients, and keep your availability status updated.'
    }, {
      question: 'Will employers contact me directly?',
      answer: "Yes, once you apply for a job, employers can contact you through our messaging system. If they're interested in your application, they may request an interview or additional information."
    }],
    Payments: [{
      question: 'How do payments work on the platform?',
      answer: 'We offer secure payment processing between employers and workers. Employers can pay for services directly through our platform, and workers receive payments to their connected bank account or payment method.'
    }, {
      question: 'What payment methods are accepted?',
      answer: 'We accept major credit cards, debit cards, PayPal, and bank transfers for service payments. For subscription payments, we accept credit cards and PayPal.'
    }, {
      question: 'When do I get paid for completed work?',
      answer: 'Payments are typically processed within 3-5 business days after the employer marks the job as complete and approves payment. Funds are then transferred to your connected payment method.'
    }, {
      question: 'Are there any fees for receiving payments?',
      answer: 'Free Tier users have a 5% service fee on payments. Paid Plan subscribers have a reduced 3% fee. Enterprise accounts can negotiate custom fee structures.'
    }],
    'Safety & Security': [{
      question: 'How do you verify users on the platform?',
      answer: 'We offer optional identity verification for all users. Paid and Enterprise users receive priority verification, which includes ID checks and background screening for enhanced safety and trust.'
    }, {
      question: 'What should I do if I encounter suspicious activity?',
      answer: "If you notice suspicious behavior or potential scams, immediately report it using the 'Report' button on the relevant profile or job posting. Our safety team will investigate promptly."
    }, {
      question: 'How is my personal information protected?',
      answer: 'We use industry-standard encryption and security measures to protect your data. We never share your personal information with third parties without your consent. For more details, please review our Privacy Policy.'
    }, {
      question: 'What safety tips do you recommend when meeting in person?',
      answer: "Always meet in public places for initial meetings, inform someone about your whereabouts, verify the other person's identity beforehand, and trust your instincts. We recommend video calls before in-person meetings."
    }]
  };
  const filteredFaqs = activeCategory ? faqs[activeCategory] : [];
  return <div className="container mx-auto px-4 py-16">
      <div className="max-w-5xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-800 mb-8">Help Center</h1>
        {/* Search */}
        <div className="mb-12">
          <div className="relative max-w-2xl mx-auto mb-8">
            <input type="text" placeholder="Search for answers..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full py-4 px-5 pr-12 rounded-full border border-gray-300 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent shadow-sm" />
            <div className="absolute right-4 top-1/2 transform -translate-y-1/2">
              <SearchIcon size={24} className="text-gray-400" />
            </div>
          </div>
          <div className="flex flex-wrap justify-center gap-3">
            {categories.map((category, index) => <button key={index} onClick={() => setActiveCategory(category)} className={`px-5 py-2.5 rounded-full text-sm font-medium transition-colors ${activeCategory === category ? 'bg-teal-500 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}>
                {category}
              </button>)}
          </div>
        </div>
        {/* FAQ Accordion */}
        <div className="space-y-4">
          <h2 className="text-2xl font-bold text-gray-800 mb-6">
            {activeCategory}
          </h2>
          {filteredFaqs.map((faq, index) => <FaqItem key={index} question={faq.question} answer={faq.answer} />)}
        </div>
        <div className="mt-16 bg-teal-50 p-8 rounded-lg">
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">
            Still have questions?
          </h2>
          <p className="text-gray-600 mb-6">
            Our support team is here to help you with any issues or questions
            you might have.
          </p>
          <div className="flex flex-col sm:flex-row gap-4">
            <button className="bg-teal-500 text-white px-6 py-3 rounded-full font-medium hover:bg-teal-600 transition-colors shadow-sm flex-1">
              Contact Support
            </button>
            <button className="bg-white border border-teal-500 text-teal-500 px-6 py-3 rounded-full font-medium hover:bg-teal-50 transition-colors shadow-sm flex-1">
              Submit a Ticket
            </button>
          </div>
        </div>
      </div>
    </div>;
}
function FaqItem({
  question,
  answer
}: {
  question: string;
  answer: string;
}) {
  const [isOpen, setIsOpen] = useState(false);
  return <div className="border border-gray-200 rounded-lg">
      <button className="flex justify-between items-center w-full p-5 text-left bg-white hover:bg-gray-50 transition-colors rounded-lg focus:outline-none" onClick={() => setIsOpen(!isOpen)}>
        <h3 className="text-lg font-medium text-gray-800">{question}</h3>
        <ChevronDownIcon size={20} className={`text-gray-500 transition-transform ${isOpen ? 'transform rotate-180' : ''}`} />
      </button>
      {isOpen && <div className="p-5 pt-0 border-t border-gray-200">
          <p className="text-gray-600">{answer}</p>
        </div>}
    </div>;
}